// Security + validation gate: only the Lambda / workflow B (which hold WEBHOOK_SECRET) may trigger this workflow.
const secret = $env.WEBHOOK_SECRET;
const first = $input.first().json;
const got = (first.headers || {})['x-webhook-secret'];
if (secret && got !== secret) throw new Error('Invalid webhook secret');
const batchId = (first.body || {}).batch_id || '';
if (!/^[0-9a-f-]{36}$/i.test(batchId)) throw new Error('Invalid batch_id');
return [{ json: { batch_id: batchId } }];

// STAGE 3 (prep): pack near-miss pairs into batches so ONE LLM call judges many pairs (25 by default).
const size = parseInt($env.LLM_BATCH_SIZE || '25', 10);
const maxPairs = parseInt($env.LLM_MAX_PAIRS || '200', 10);
const rows = $input.all().map(i => i.json).filter(r => r.match_id).slice(0, maxPairs);
if (!rows.length) return [{ json: { skip: true } }];
const out = [];
for (let i = 0; i < rows.length; i += size) {
  const pairs = rows.slice(i, i + size);
  const payload = pairs.map(p => ({
    match_id: p.match_id,
    applicant: { monthly_income: p.monthly_income, credit_score: p.credit_score,
                 employment_status: p.employment_status, age: p.age },
    product: { name: p.product_name, interest_rate: p.interest_rate, min_monthly_income: p.min_monthly_income,
               min_credit_score: p.min_credit_score, notes: p.eligibility_text },
  }));
  const prompt = 'You are a careful loan pre-screening assistant. Each item is an applicant who narrowly misses ONE ' +
    'numeric threshold (income or credit score) of a personal loan product. Mark eligible=true ONLY if the shortfall is ' +
    'marginal AND the rest of the profile compensates (e.g. stable salaried employment, income well above the minimum, ' +
    'strong score). Otherwise eligible=false. Return ONLY a JSON array: ' +
    '[{"match_id": number, "eligible": boolean, "reason": string (max 20 words, addressed to the applicant)}]. ' +
    'ITEMS: ' + JSON.stringify(payload);
  out.push({ json: { skip: false, ids: pairs.map(p => p.match_id), prompt } });
}
return out;

// Turn each LLM answer into verdicts. Conservative fallback: if the LLM is unreachable, near misses are rejected.
const batches = $('Build LLM Batches').all();
return $input.all().map((item, i) => {
  const ids = batches[i].json.ids;
  let verdicts = [];
  try {
    const parsed = JSON.parse(item.json.candidates[0].content.parts[0].text);
    const arr = Array.isArray(parsed) ? parsed : (parsed.results || []);
    verdicts = arr.filter(v => ids.includes(Number(v.match_id)))
                  .map(v => ({ match_id: Number(v.match_id), eligible: v.eligible === true,
                               reason: String(v.reason || '').slice(0, 200) }));
  } catch (e) { /* fall through to fallback */ }
  const seen = new Set(verdicts.map(v => v.match_id));
  for (const id of ids) if (!seen.has(id)) verdicts.push({ match_id: id, eligible: false, reason: 'llm_unavailable' });
  return { json: { verdicts } };
});
